import{_ as o,o as e,c as i,ag as s}from"./chunks/framework.D5hoimZQ.js";const q=JSON.parse('{"title":"设计与美学","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"topics/design/index.md","filePath":"topics/design/index.md"}'),a={name:"topics/design/index.md"};function r(n,t,l,u,h,d){return e(),i("div",null,[...t[0]||(t[0]=[s('<h1 id="设计与美学" tabindex="-1">设计与美学 <a class="header-anchor" href="#设计与美学" aria-label="Permalink to &quot;设计与美学&quot;">​</a></h1><blockquote><p>设计史、视觉语言、美学背后的商业与政治机制</p></blockquote><h2 id="文件列表" tabindex="-1">文件列表 <a class="header-anchor" href="#文件列表" aria-label="Permalink to &quot;文件列表&quot;">​</a></h2><ul><li><a href="/zhishiku-reading/topics/design/minimalism-death-of-detail.html">🌀 极简主义的胜利，还是细节的死亡？</a> — <strong>主文档</strong>。从阮一峰周刊 #216 溯源到原始推特长贴《The Danger of Minimalist Design》，含 110 年设计史谱系（Loos 1910 / 包豪斯 / 国际风格 / Rams / Venturi / 扁平化 / Glassmorphism）、极简必至的三层机制（成本、最小冒犯、去地方性）、四项代价（身份消失、Nielsen 2017 扁平界面慢 22%、敌意建筑、Corporate Memphis）、&quot;少而更好 vs 少而更便宜&quot;判据</li><li><a href="/zhishiku-reading/topics/design/bauhaus-to-rams.html">🏛 从包豪斯到 Rams：少而更好的谱系</a> — 包豪斯（1919–1933 三城三段三校长 + Vorkurs）→ 国际风格（1932 MoMA，命名与三原则）→ Dieter Rams 十原则逐条 → 日本民艺运动（柳宗悦&quot;用之美&quot;）；点出真正的传动轴是乌尔姆（HfG Ulm）而非包豪斯本身</li><li><a href="/zhishiku-reading/topics/design/hostile-architecture.html">🚫 敌意建筑：当&quot;变简单&quot;变成不让人久留</a> — 术语谱系（hostile/defensive/unpleasant design 的边界）、形式清单（尖刺、分段长椅、防露营巨石、Mosquito 超声波）、2014 伦敦尖刺十天拆除全记录、Camden bench 的<strong>维基版 vs 厂商版不一致说明书</strong>、&quot;无障碍话术&quot;的两处厂商自证、现场四问判据</li><li><a href="/zhishiku-reading/topics/design/logo-convergence.html">🔷 品牌视觉的趋同：大公司 logo 为什么越来越像</a> — blanding 的八年周期（2018 命名 → 2020 olding → 2023 复古回潮）、按核实状态分层的案例表（Gap 一周撤回 / Google Product Sans / Mastercard 2019 去字标 / Burberry by Peter Saville / X 的投稿字型）、四个机制、六问判据</li><li><a href="/zhishiku-reading/topics/design/eastern-negative-space.html">🀄 留白不是极简：有意味的空 vs 没东西</a> — 马远&quot;马一角&quot;与夏圭&quot;夏半边&quot;、<strong>《寒江独钓图》东博官方说明的自我拆穿</strong>（伝馬遠筆 + 推测为裁剪而成）、引文考古（画筌 ✅ / 艺舟双楫 ✅ / 南宗抉秘 误归 ❌ / 宗白华 未核实）、园冶借景四分类、原研哉&quot;待填的空&quot;与 MUJI 两个阶段的叙事转移、4′33″</li><li><a href="/zhishiku-reading/topics/design/less-but-better-engineering.html">🛠 &quot;少而更好&quot;的工程版：把判据变成可执行的评审清单</a> — 装饰性复杂度 vs 承载性复杂度对照表、六条评审判据（删除测试 / 恢复成本 / 收益归属 / 可解释性守恒 / 默认值原则 / 推迟≠删除）、四个高频误用（YAGNI、极简依赖、单体 vs 分布式、上下文压缩）</li></ul><h2 id="本主题的母题" tabindex="-1">本主题的母题 <a class="header-anchor" href="#本主题的母题" aria-label="Permalink to &quot;本主题的母题&quot;">​</a></h2><ul><li><strong>默认值 vs 选择</strong>：批判的对象应是&quot;社会默认&quot;，而不是个人审美选择</li><li><strong>&quot;少&quot;的两个相反含义</strong>：省略装饰（增值）vs 省略能力（减值）——这个判据贯穿全主题：品牌（省字保留形）、城市（省装饰还是省掉那个人）、工程（省冗余还是省错误处理）、美学（省出来 vs 经营出来）</li><li><strong>设计是权力与成本的表征</strong>：公共空间里&quot;变简单&quot;常常等于&quot;不让人久留&quot;</li><li><strong>同一外观，不同动机</strong>：成本型极简、克制型极简、排斥型&quot;极简&quot;、留白，外观相近、机制相反——<strong>靠外观分不出来，只能查动机与语境</strong></li></ul><h2 id="方法沉淀-本主题沿线形成的核查纪律" tabindex="-1">方法沉淀（本主题沿线形成的核查纪律） <a class="header-anchor" href="#方法沉淀-本主题沿线形成的核查纪律" aria-label="Permalink to &quot;方法沉淀（本主题沿线形成的核查纪律）&quot;">​</a></h2><ul><li><strong>引文考古</strong>：引用古话前先做原文全文检索。本主题已证伪一例（《南宗抉秘》无&quot;无画处&quot;字样 → 华琳归属为误归），并发现一处语境剥离（&quot;计白当黑&quot;出自书论，非设计论述）</li><li><strong>点名案例必须带年份 + 设计方</strong>，否则降级为 ⚠️ 待核实，不进正文论证</li><li><strong>官方说明优先于二手叙事</strong>：东博对《寒江独钓图》的登记信息直接改写了&quot;留白典范&quot;的教科书说法</li><li><strong>清单冲突要并列</strong>：Camden bench 的维基版与厂商版阻止清单不一致，两种都写，不合并</li></ul><hr><blockquote><p>整理日期：2026-09-20</p></blockquote>',10)])])}const c=o(a,[["render",r]]);export{q as __pageData,c as default};
